function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 25);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 25, H/2 + 35);
  ctx.lineTo(W/2, H/2 + 25);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 25, H/2 + 35);
  ctx.lineTo(W/2, H/2 + 25);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 15 + 10 * Math.sin(t), H/2 - 10);
  ctx.lineTo(W/2 - 30, H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 15 - 10 * Math.sin(t), H/2 - 10);
  ctx.lineTo(W/2 + 30, H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 30, H/2 + 10, 5, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 30, H/2 + 10, 5, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.restore();
}
